import {
  createBrowserRouter,
  RouterProvider,
  redirect,
  type RouteObject,
} from 'react-router';

let isAuthed = false;
export function setAuthed(v: boolean) {
  isAuthed = v;
}

export const routes: RouteObject[] = [
  { path: '/login', element: <p>please log in</p> },
  {
    path: '/profile',
    loader: () => {
      if (!isAuthed) throw redirect('/login');
      return null;
    },
    element: <p>welcome</p>,
  },
];

export const router = createBrowserRouter(routes);

export function App() {
  return <RouterProvider router={router} />;
}
